/**
 * The generated project rules file (#1027): the guarded write rules, independent of the CLI.
 * An absent file is created; a pdb-generated file is replaced; a hand-written file is refused
 * and never overwritten; identical content is a no-op; a symbolic link is never written through.
 */
import { mkdtemp, readFile, rm, symlink, writeFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { describe, expect, it } from "vite-plus/test";
import {
  installRulesFile,
  RULES_FILE_MARKER,
  RULES_FILE_NAME,
  withRulesFile,
} from "./rulesfile.js";

const markdown = `${RULES_FILE_MARKER}{"v":1,"policyVersion":1,"rulesHash":"abc","englishModelVersion":3} -->\n\n# Rules\n`;

describe("generated rules file (#1027)", () => {
  it("creates, replaces a generated file, keeps identical content, and refuses a foreign file", () => {
    expect(withRulesFile(null, markdown)).toEqual({ text: markdown });
    expect(withRulesFile(markdown, markdown)).toEqual({ unchanged: true });
    const older = `${RULES_FILE_MARKER}{"v":1,"policyVersion":1,"rulesHash":"old","englishModelVersion":3} -->\n\n# Rules\n`;
    expect(withRulesFile(older, markdown)).toEqual({ text: markdown });
    expect(withRulesFile("# my notes\n", markdown)).toEqual({
      refuse: `${RULES_FILE_NAME} already exists and was not generated by pdb; move it aside or delete it, then retry`,
    });
  });

  it("writes through the locked writer and refuses a symbolic link", async () => {
    const dir = await mkdtemp(join(tmpdir(), "pdb-rulesfile-"));
    try {
      const first = await installRulesFile(dir, markdown);
      expect(first).toMatchObject({ status: "written", file: RULES_FILE_NAME });
      expect(await readFile(join(dir, RULES_FILE_NAME), "utf8")).toBe(markdown);
      expect(await installRulesFile(dir, markdown)).toMatchObject({ status: "kept" });

      await writeFile(join(dir, "handwritten.md"), "# notes\n");
      await rm(join(dir, RULES_FILE_NAME));
      await symlink(join(dir, "handwritten.md"), join(dir, RULES_FILE_NAME));
      const linked = await installRulesFile(dir, markdown);
      expect(linked.status).toBe("not-written");
      expect("reason" in linked ? linked.reason : "").toContain("symbolic link");
      expect(await readFile(join(dir, "handwritten.md"), "utf8")).toBe("# notes\n");
    } finally {
      await rm(dir, { recursive: true, force: true });
    }
  });
});
